self.addEventListener('install', e => {
  e.waitUntil(caches.open(BASE).then(c => c.addAll(FICHIERS_BASE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('papy-base-') && k !== BASE) await caches.delete(k);
    const ph = await caches.open(PHOTOS), voulues = new Set(FICHIERS_PHOTOS.map(f => new URL(f, self.registration.scope).href));
    for (const r of await ph.keys()) if (!voulues.has(r.url)) await ph.delete(r);
    await self.clients.claim();
  })());
});

/* Téléchargement de toutes les photos, demandé par la page ; on renvoie l'avancement */
let enCours = null;
async function telecharger() {
  const ph = await caches.open(PHOTOS), total = FICHIERS_PHOTOS.length;
  let fait = 0, erreurs = 0;
  const annoncer = async (fini) => { for (const c of await self.clients.matchAll()) c.postMessage({ type: 'horsligne', fait, total, fini, erreurs }); };
  const file = FICHIERS_PHOTOS.slice();
  let dernier = 0;
  async function ouvrier() {
    while (file.length) {
      const f = file.shift(), url = new URL(f, self.registration.scope).href;
      if (!(await ph.match(url))) {
        try { const r = await fetch(url); if (r.ok) await ph.put(url, r); else erreurs++; } catch (_) { erreurs++; }
      }
      fait++;
      if (Date.now() - dernier > 400) { dernier = Date.now(); annoncer(false); }
    }
  }
  await Promise.all([ouvrier(), ouvrier(), ouvrier(), ouvrier()]);
  await annoncer(true);
}
self.addEventListener('message', e => {
  if (e.data && e.data.type === 'telecharger') {
    if (!enCours) enCours = telecharger().finally(() => { enCours = null; });
    e.waitUntil && e.waitUntil(enCours);
  }
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    e.respondWith((async () => {
      const trouve = await caches.match(req, { ignoreSearch: true });
      if (trouve) return trouve;
      try {
        const r = await fetch(req);
        if (r.ok && url.pathname.includes('/livres/images/recettes/')) (await caches.open(PHOTOS)).put(req, r.clone());
        return r;
      } catch (err) {
        if (req.mode === 'navigate') return (await caches.match(new URL('./', self.registration.scope).href)) || Response.error();
        throw err;
      }
    })());
  } else if (/fonts\.(googleapis|gstatic)\.com$/.test(url.hostname)) {
    e.respondWith((async () => {
      const c = await caches.open(POLICES), t = await c.match(req);
      const reseau = fetch(req).then(r => { c.put(req, r.clone()); return r; }).catch(() => t);
      return t || reseau;
    })());
  }
});
